// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;
    function setUp() public { c = new VaultAdapter(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller.code.length == 0);
        bytes32 expectedSlot = bytes32(uint256(keccak256("eip1967.proxy.implementation")) - 1);
        vm.prank(caller);
        bytes32 result = c.proxiableUUID();
        assertTrue(result == expectedSlot, "proxiableUUID must return ERC1967 implementation slot");
    }
}
